begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select no_plan();

select ok(to_regclass(name) is not null,name||' exists') from unnest(array[
 'public.research_evaluations','public.research_evidence_items','public.research_evidence_versions','public.research_snapshots','public.research_snapshot_members','public.research_follow_up_records','public.research_raw_observations','public.research_verified_events','public.research_outcomes','public.research_outcome_event_members','public.research_review_adjudications']) name;
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid=name::regclass),name||' forces RLS') from unnest(array['public.research_evidence_items','public.research_evidence_versions','public.research_snapshots','public.research_follow_up_records','public.research_raw_observations','public.research_verified_events','public.research_outcomes','public.research_review_adjudications']) name;
select ok(not has_table_privilege(role_name,'public.research_evidence_versions','SELECT'),role_name||' cannot directly read research evidence') from unnest(array['anon','authenticated','service_role']) role_name;
select ok(not has_table_privilege(role_name,'public.research_outcomes','INSERT'),role_name||' cannot directly write research outcomes') from unnest(array['anon','authenticated','service_role']) role_name;
select ok(to_regprocedure(name) is not null,name||' exists') from unnest(array[
 'public.create_synthetic_research_evidence(uuid,uuid,text,uuid,text,text,text,timestamptz,timestamptz,text,jsonb,jsonb,uuid,uuid,uuid)',
 'public.correct_synthetic_research_evidence_version(uuid,uuid,text,jsonb,text,uuid)',
 'public.freeze_synthetic_research_snapshot(uuid,text,uuid,text,uuid,uuid[],text,text,uuid)',
 'public.complete_synthetic_research_baseline(uuid,uuid,uuid)',
 'public.create_synthetic_research_follow_up(uuid,text,uuid,uuid,uuid)',
 'public.complete_synthetic_research_follow_up(uuid,uuid,uuid,uuid)',
 'public.record_synthetic_research_observation(uuid,uuid,text,text,jsonb,timestamptz,uuid)',
 'public.verify_synthetic_research_event(uuid,uuid,uuid,text,text,text,uuid)',
 'public.propose_synthetic_research_outcome(uuid,uuid,text,uuid,text,uuid[],text,uuid)',
 'public.adjudicate_synthetic_research_outcome(uuid,uuid,text,text,text,uuid)']) name;
select ok((select prosecdef and proconfig @> array['search_path=public, pg_catalog'] from pg_proc where oid=to_regprocedure(name)),name||' is controlled security definer') from unnest(array[
 'public.create_synthetic_research_evidence(uuid,uuid,text,uuid,text,text,text,timestamptz,timestamptz,text,jsonb,jsonb,uuid,uuid,uuid)',
 'public.freeze_synthetic_research_snapshot(uuid,text,uuid,text,uuid,uuid[],text,text,uuid)',
 'public.verify_synthetic_research_event(uuid,uuid,uuid,text,text,text,uuid)',
 'public.adjudicate_synthetic_research_outcome(uuid,uuid,text,text,text,uuid)']) name;

insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('00000000-0000-0000-0000-000000000000','b1000000-0000-4000-8000-000000000001','authenticated','authenticated','admin51@test.local','','2026-01-01','{"provider":"email","providers":["email"]}','{}','2026-01-01','2026-01-01'),
('00000000-0000-0000-0000-000000000000','b1000000-0000-4000-8000-000000000002','authenticated','authenticated','verifier51@test.local','','2026-01-01','{"provider":"email","providers":["email"]}','{}','2026-01-01','2026-01-01'),
('00000000-0000-0000-0000-000000000000','b1000000-0000-4000-8000-000000000003','authenticated','authenticated','reviewer51@test.local','','2026-01-01','{"provider":"email","providers":["email"]}','{}','2026-01-01','2026-01-01'),
('00000000-0000-0000-0000-000000000000','b1000000-0000-4000-8000-000000000011','authenticated','authenticated','participant51@test.local','','2026-01-01','{"provider":"email","providers":["email"]}','{}','2026-01-01','2026-01-01');
insert into public.staff_members(id,auth_user_id,staff_code,full_name,email,status,created_at) values
('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','WPAG-STF-951001','Wave 2 Admin','admin51@test.local','active','2026-01-01'),
('b2000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000002','WPAG-STF-951002','Wave 2 Verifier','verifier51@test.local','active','2026-01-01'),
('b2000000-0000-4000-8000-000000000003','b1000000-0000-4000-8000-000000000003','WPAG-STF-951003','Wave 2 Reviewer','reviewer51@test.local','active','2026-01-01');
insert into public.staff_member_roles(staff_member_id,staff_role_id,is_active,assigned_at)
select s.id,r.id,true,'2026-01-01' from public.staff_members s join public.staff_roles r on r.role_code=case s.id when 'b2000000-0000-4000-8000-000000000001' then 'administrator' when 'b2000000-0000-4000-8000-000000000002' then 'evidence_verifier' else 'reviewer' end where s.id::text like 'b2000000%';
insert into public.participants(id,auth_user_id,participant_code,lifecycle_status,created_at) values('b3000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000011','WPAG-951001','active','2026-01-01');

create temporary table w2(key text primary key,value uuid not null);
insert into w2 select 'enrollment',enrollment_id from public.create_or_get_research_enrollment('b3000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','FSH Phase 1','PUR-01','Protocol-v1','Consent-v0.2','Privacy-v0.1','Lifecycle-v0.2','Evidence-v0.1','synthetic_test','b9000000-0000-4000-8000-000000000001');
select lives_ok(format($q$select * from public.record_research_consent_transition(%L,'b1000000-0000-4000-8000-000000000001','PRESENTED','Consent-v1',repeat('a',64),'Protocol-v1','{"FSH":"FSH-PLAN-v1"}',array['FSH'],array['BASELINE_RESEARCH','FOLLOW_UP_RESEARCH'],true,'en-v1','INTERNAL_SYNTHETIC','{}','PRESENT','b9000000-0000-4000-8000-000000000002')$q$,(select value from w2 where key='enrollment')),'consent presented');
select lives_ok(format($q$select * from public.record_research_consent_transition(%L,'b1000000-0000-4000-8000-000000000011','GRANTED','Consent-v1',repeat('a',64),'Protocol-v1','{"FSH":"FSH-PLAN-v1"}',array['FSH'],array['BASELINE_RESEARCH','FOLLOW_UP_RESEARCH'],true,'en-v1','INTERNAL_SYNTHETIC','{"affirmative":true}','GRANT','b9000000-0000-4000-8000-000000000003')$q$,(select value from w2 where key='enrollment')),'synthetic consent granted');
select lives_ok(format($q$select * from public.record_research_privacy_binding(%L,'b1000000-0000-4000-8000-000000000001','PUR-01',array['RESEARCH_IDENTITY','FINANCIAL_EVIDENCE','RESEARCH_EVENT','ADJUDICATED_OUTCOME','AUDIT_PROVENANCE'],'STANDARD_RESTRICTED','RESTRICTED_RESEARCH','PURPOSE_SCOPED','RC-01','ACTIVE_RETAIN','NO_EXTERNAL_SHARING','NOT_AUTHORIZED','NONE',true,true,true,true,false,false,'SYNTHETIC_OPEN','b9000000-0000-4000-8000-000000000004')$q$,(select value from w2 where key='enrollment')),'privacy gate opened');

insert into w2 select 'version1',evidence_version_id from public.create_synthetic_research_evidence((select value from w2 where key='enrollment'),null,'FSH','b1000000-0000-4000-8000-000000000001','PUR-01','SYNTHETIC-LOAD-1','SYSTEM_RECORDED','2026-08-11','2026-08-11','PRESENT','{"value":100}','{"synthetic":true}',null,null,'b9000000-0000-4000-8000-000000000005');
insert into w2 select 'evaluation1',evaluation_id from public.research_evidence_items i join public.research_evidence_versions v on v.evidence_item_id=i.id where v.id=(select value from w2 where key='version1');
select is((select value_state from public.research_evidence_versions where id=(select value from w2 where key='version1')),'PRESENT','present value preserved');
select throws_ok(format($q$select * from public.create_synthetic_research_evidence(%L,null,'FSH','b1000000-0000-4000-8000-000000000001','PUR-01','BAD-ZERO','SYSTEM_RECORDED','2026-08-11','2026-08-11','CONFIRMED_ZERO','{"value":2}','{"synthetic":true}',null,null,'b9000000-0000-4000-8000-000000000006')$q$,(select value from w2 where key='enrollment')),'P1001','Research evidence value or authority state is invalid.','confirmed zero requires numeric zero');
select throws_ok(format($q$select * from public.create_synthetic_research_evidence(%L,null,'FSH','b1000000-0000-4000-8000-000000000001','PUR-01','BAD-MISSING','SYSTEM_RECORDED','2026-08-11','2026-08-11','MISSING','{"value":0}','{"synthetic":true}',null,null,'b9000000-0000-4000-8000-000000000007')$q$,(select value from w2 where key='enrollment')),'P1001','Research evidence value or authority state is invalid.','missing never becomes zero');
insert into w2 values('version2',public.correct_synthetic_research_evidence_version((select value from w2 where key='version1'),'b1000000-0000-4000-8000-000000000001','PRESENT','{"value":120}','SOURCE_CORRECTION','b9000000-0000-4000-8000-000000000008'));
select is((select predecessor_version_id from public.research_evidence_versions where id=(select value from w2 where key='version2')),(select value from w2 where key='version1'),'correction is append-only successor');
insert into w2 values('snapshot1',public.freeze_synthetic_research_snapshot((select value from w2 where key='enrollment'),'FSH','b1000000-0000-4000-8000-000000000001','BASELINE',null,array[(select value from w2 where key='version2')],'COMPLETE','CURRENT','b9000000-0000-4000-8000-000000000009'));
select throws_ok(format($q$update public.research_snapshots set completeness_status='INCOMPLETE' where id=%L$q$,(select value from w2 where key='snapshot1')),'P1001','Research Wave 2 records are append-only.','frozen snapshot is immutable');
insert into w2 values('version3',public.correct_synthetic_research_evidence_version((select value from w2 where key='version2'),'b1000000-0000-4000-8000-000000000001','PRESENT','{"value":125}','AFTER_FREEZE','b9000000-0000-4000-8000-000000000010'));
select is((select evidence_version_id from public.research_snapshot_members where snapshot_id=(select value from w2 where key='snapshot1')),(select value from w2 where key='version2'),'post-freeze correction does not change manifest');
insert into w2 values('snapshot2',public.freeze_synthetic_research_snapshot((select value from w2 where key='enrollment'),'FSH','b1000000-0000-4000-8000-000000000001','BASELINE',(select value from w2 where key='snapshot1'),array[(select value from w2 where key='version3')],'COMPLETE','CURRENT','b9000000-0000-4000-8000-000000000011'));
select is((select predecessor_snapshot_id from public.research_snapshots where id=(select value from w2 where key='snapshot2')),(select value from w2 where key='snapshot1'),'snapshot succession explicit');
select lives_ok(format($q$select public.complete_synthetic_research_baseline(%L,'b1000000-0000-4000-8000-000000000001','b9000000-0000-4000-8000-000000000012')$q$,(select value from w2 where key='snapshot2')),'baseline completes only from governed snapshot');
select is((select lifecycle_status from public.research_enrollment_status_history where enrollment_id=(select value from w2 where key='enrollment') order by recorded_at desc,id desc limit 1),'BASELINE_COMPLETE','baseline status recorded');
select is((select count(*) from public.research_enrollment_status_history where enrollment_id=(select value from w2 where key='enrollment') and lifecycle_status='ACTIVE_RESEARCH'),0::bigint,'baseline never activates research');

insert into w2 select 'followup1',follow_up_id from public.create_synthetic_research_follow_up((select value from w2 where key='enrollment'),'FSH','b1000000-0000-4000-8000-000000000001',(select value from w2 where key='snapshot2'),'b9000000-0000-4000-8000-000000000013');
insert into w2 select 'evaluation2',evaluation_id from public.research_follow_up_records where id=(select value from w2 where key='followup1');
insert into w2 select 'followup_version',evidence_version_id from public.create_synthetic_research_evidence((select value from w2 where key='enrollment'),(select value from w2 where key='evaluation2'),'FSH','b1000000-0000-4000-8000-000000000001','PUR-01','SYNTHETIC-FOLLOWUP-1','SYSTEM_RECORDED','2026-08-11','2026-08-11','CONFIRMED_ZERO','{"value":0}','{"synthetic":true}',null,null,'b9000000-0000-4000-8000-000000000014');
insert into w2 values('followup_snapshot',public.freeze_synthetic_research_snapshot((select value from w2 where key='enrollment'),'FSH','b1000000-0000-4000-8000-000000000001','FOLLOW_UP',(select value from w2 where key='snapshot2'),array[(select value from w2 where key='followup_version')],'COMPLETE','CURRENT','b9000000-0000-4000-8000-000000000015'));
select lives_ok(format($q$select public.complete_synthetic_research_follow_up(%L,%L,'b1000000-0000-4000-8000-000000000001','b9000000-0000-4000-8000-000000000016')$q$,(select value from w2 where key='followup1'),(select value from w2 where key='followup_snapshot')),'follow-up completes with frozen current snapshot');
select lives_ok(format($q$select * from public.create_synthetic_research_follow_up(%L,'FSH','b1000000-0000-4000-8000-000000000001',%L,'b9000000-0000-4000-8000-000000000017')$q$,(select value from w2 where key='enrollment'),(select value from w2 where key='followup_snapshot')),'multiple deterministic follow-ups supported without cadence');

insert into w2 values('observation',public.record_synthetic_research_observation((select value from w2 where key='followup_snapshot'),'b1000000-0000-4000-8000-000000000001','SYSTEM_RECORDED','OBS-CONTINUITY','{"synthetic":true}','2026-08-11','b9000000-0000-4000-8000-000000000018'));
select is((select count(*) from public.research_verified_events where raw_observation_id=(select value from w2 where key='observation')),0::bigint,'raw observation is not a verified event');
select throws_ok(format($q$select public.verify_synthetic_research_event(%L,%L,'b1000000-0000-4000-8000-000000000001','CONTINUITY_MAINTAINED','SUFFICIENT','VERIFY','b9000000-0000-4000-8000-000000000019')$q$,(select value from w2 where key='observation'),(select value from w2 where key='followup_version')),'P1001','Event verifier independence or lineage is invalid.','observation recorder cannot verify event');
insert into w2 values('event',public.verify_synthetic_research_event((select value from w2 where key='observation'),(select value from w2 where key='followup_version'),'b1000000-0000-4000-8000-000000000002','CONTINUITY_MAINTAINED','SUFFICIENT','INDEPENDENT_VERIFY','b9000000-0000-4000-8000-000000000020'));
select throws_ok(format($q$select public.verify_synthetic_research_event(%L,%L,'b1000000-0000-4000-8000-000000000002','REPEATED_PRESSURE_MANIFESTATION','SUFFICIENT','RESERVED','b9000000-0000-4000-8000-000000000021')$q$,(select value from w2 where key='observation'),(select value from w2 where key='followup_version')),'P1001','Reserved or unauthorized research event class is prohibited.','reserved event prohibited');
insert into w2 values('outcome',public.propose_synthetic_research_outcome((select value from w2 where key='enrollment'),(select value from w2 where key='evaluation2'),'FSH','b1000000-0000-4000-8000-000000000001','CONTINUITY_PRESERVED',array[(select value from w2 where key='event')],'SYNTHETIC_PROPOSAL','b9000000-0000-4000-8000-000000000022'));
select throws_ok(format($q$select * from public.adjudicate_synthetic_research_outcome(%L,'b1000000-0000-4000-8000-000000000001','CONFIRMED','SUFFICIENT','SELF','b9000000-0000-4000-8000-000000000023')$q$,(select value from w2 where key='outcome')),'P1001','Outcome adjudicator independence is invalid.','proposer cannot adjudicate');
select lives_ok(format($q$select * from public.adjudicate_synthetic_research_outcome(%L,'b1000000-0000-4000-8000-000000000003','CONFIRMED','SUFFICIENT','INDEPENDENT','b9000000-0000-4000-8000-000000000024')$q$,(select value from w2 where key='outcome')),'independent reviewer adjudicates outcome');
select throws_ok(format($q$select public.propose_synthetic_research_outcome(%L::uuid,%L::uuid,'FSH','b1000000-0000-4000-8000-000000000001','Stable',array[%L::uuid],'STATE_LEAK','b9000000-0000-4000-8000-000000000025')$q$,(select value from w2 where key='enrollment'),(select value from w2 where key='evaluation2'),(select value from w2 where key='event')),'P1001','Reserved, final-State, or unauthorized outcome class is prohibited.','final System State cannot be outcome');
select ok((select bool_and(actual_enrollment_status in ('BLOCKED','NOT_AUTHORIZED') and evidence_collection_status in ('BLOCKED','NOT_AUTHORIZED') and pilot_status='NOT_AUTHORIZED' and production_status='NOT_AUTHORIZED') from public.research_release_firewall),'release firewall remains blocked');
select throws_ok(format($q$update public.research_verified_events set event_status='SUPERSEDED' where id=%L$q$,(select value from w2 where key='event')),'P1001','Research Wave 2 records are append-only.','verified events are immutable');
select ok((select count(*)>=8 from public.research_control_audit_events where enrollment_id=(select value from w2 where key='enrollment') and event_type like 'RESEARCH_%'),'Wave 2 material actions are audited');

select * from finish(); rollback;
